    "id": "wiki.proposal-workflow",
    "objectId": "wiki.proposal-workflow",
    "title": "Proposal Workflow",
    "description": "Proposal Workflow defines how Block Ops turns a qualified prospect into a personalized proposal, reviews it internally, sends it cleanly, and follows up without losing momentum.",
    "category": "wiki-sales",
    "status": "draft",
    "publishBucket": "internal-draft",
    "reviewer": "Samir / Adrian / Max",
