    "objectId": "wiki.acquisition-growth-strategy",
    "title": "Acquisition / Growth Strategy",
    "description": "Acquisition / Growth Strategy defines internal M3 hypotheses for channels, target fit, qualification, ownership, and controlled growth learning.",
    "category": "wiki-sales",
    "status": "draft",
    "publishBucket": "internal-current-draft",
    "reviewer": "Samir / Adrian",
